    const mk = (w, h) => { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; };

    // Everything enclosed by the sticker's outline is vinyl too: flood the outside of a coarse alpha mask from the
    // border, and whatever stays dry inside is a hole to fill
    function fillHoles(sil, W, H) {
        const f = Math.min(1, 200 / Math.max(W, H));
        const w = Math.max(2, Math.round(W * f)), h = Math.max(2, Math.round(H * f));
        const small = mk(w, h), s = small.getContext('2d', { willReadFrequently: true });
        s.drawImage(sil, 0, 0, w, h);
        const img = s.getImageData(0, 0, w, h), a = img.data;
        const out = new Uint8Array(w * h), stack = [];
        const push = (i) => { if (!out[i] && a[i * 4 + 3] < 110) { out[i] = 1; stack.push(i); } };
        for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x); }
        for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1); }
        while (stack.length) {
            const i = stack.pop(), x = i % w;
            if (x > 0) push(i - 1);
            if (x < w - 1) push(i + 1);
            if (i >= w) push(i - w);
            if (i < w * (h - 1)) push(i + w);
        }
        let any = false;
        for (let i = 0; i < w * h; i++) {
            const hole = !out[i] && a[i * 4 + 3] < 250;
            a[i * 4] = 244; a[i * 4 + 1] = 242; a[i * 4 + 2] = 234; a[i * 4 + 3] = hole ? 255 : 0;
            any = any || hole;
        }
        if (!any) return;
        s.putImageData(img, 0, 0);
        const g = sil.getContext('2d');
        g.imageSmoothingEnabled = true;
        // Drawn a touch oversized in every direction so the coarse fill tucks under the art's edges
        for (const [dx, dy] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) g.drawImage(small, dx / f, dy / f, W, H);
    }

    // Art -> dilated outline (the die-cut) -> filled holes -> art on top, a faint vinyl sheen, a soft drop shadow
    function build(def, ppu) {
        const aw = def.w * ppu, ah = def.h * ppu;
        const B = Math.max(3, Math.round(Math.min(aw, ah) * 0.075));
        const pad = Math.ceil(B * 2.6);
        const W = Math.ceil(aw) + pad * 2, H = Math.ceil(ah) + pad * 2;
        const art = mk(W, H), a = art.getContext('2d');
        a.translate(pad, pad);
        a.scale(ppu, ppu);
        def.d(painter(a));
        const sil = mk(W, H), s = sil.getContext('2d');
        for (const [r, n] of [[B, 28], [B * 0.66, 18], [B * 0.33, 10], [0, 1]]) {
            for (let i = 0; i < n; i++) {
                const t = (i / n) * Math.PI * 2;
                s.drawImage(art, Math.cos(t) * r, Math.sin(t) * r);
            }
        }
        s.globalCompositeOperation = 'source-in';
        s.fillStyle = INK;
        s.fillRect(0, 0, W, H);
        s.globalCompositeOperation = 'source-over';
        fillHoles(sil, W, H);
        s.drawImage(art, 0, 0);
        s.globalCompositeOperation = 'source-atop';
        const sheen = s.createLinearGradient(0, 0, W, H);
        sheen.addColorStop(0, 'rgba(255,255,255,0.10)');
        sheen.addColorStop(0.38, 'rgba(255,255,255,0)');
        sheen.addColorStop(0.62, 'rgba(0,0,0,0)');
        sheen.addColorStop(1, 'rgba(0,0,0,0.12)');
        s.fillStyle = sheen;
        s.fillRect(0, 0, W, H);
        const out = mk(W, H), o = out.getContext('2d');
        o.shadowColor = 'rgba(0,0,0,0.6)';
        o.shadowBlur = B * 1.3;
        o.shadowOffsetY = B * 0.55;
        o.drawImage(sil, 0, 0);
        return { img: out, w: W, h: H, hit: Math.min(aw, ah) * 0.5 + B };
    }

    const rng = (seed) => () => {
        seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
        let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
