            delay: r() * 0.34,
            w: [0.35 + r() * 0.25, 0.3 + r() * 0.25, 0.5 + r() * 0.4, 0.25 + r() * 0.3, 0.2 + r() * 0.25],
            p: [r() * 6.28, r() * 6.28, r() * 6.28, r() * 6.28, r() * 6.28],
